import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, sub, mul, lessThan, greaterThan, vec3, mix, add, float } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group
  const root = new Group();
  root.userData.handlers = {};

  // ---------- BACKDROP PLANE ----------
  const backdropGeom = new PlaneGeometry(7, 0.35);
  const baseColor = new Color('#111117');
  const lineColor = new Color('#23232b');

  // Node material with gradient fade and hairline edges
  const uvNode = uv();

  // Fade mask (transparent at edges)
  const leftFade = sub(float(1), smoothstep(float(0), float(0.09), uvNode.x));
  const rightFade = sub(float(1), smoothstep(float(0.91), float(1.0), uvNode.x));
  const alphaMask = mul(leftFade, rightFade);

  // Hairline mask (top/bottom 0.006 units)
  const lineHeight = 0.006 / 0.35; // normalized height
  const bottomLine = lessThan(uvNode.y, float(lineHeight));
  const topLine = lessThan(float(1).sub(uvNode.y), float(lineHeight));
  const lineMask = add(bottomLine, topLine); // 0 or 1

  // Mix base color with line color based on mask
  const baseColorNode = vec3(baseColor);
  const lineColorNode = vec3(lineColor);
  const finalColor = mix(baseColorNode, lineColorNode, lineMask);

  const backdropMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: false,
    side: ctx.THREE.DoubleSide,
  });
  backdropMat.colorNode = finalColor;
  backdropMat.alphaNode = alphaMask;

  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  root.add(backdropMesh);

  // ---------- TICKER TEXT & TICKS ----------
  const stripGroup = new Group();

  // Helper to create a tick mark
  function createTick() {
    const tickGeom = new PlaneGeometry(0.02, 0.14);
    const tickMat = new MeshStandardNodeMaterial({
      color: new Color('#111117'),
      emissive: new Color('#ff2a38'),
      emissiveIntensity: 1.5,
      roughness: 0.6,
      metalness: 0.2,
      transparent: true,
      depthTest: true,
    });
    return new Mesh(tickGeom, tickMat);
  }

  // Build the strip (text + tick + gaps)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let cursorX = 0;
  const gap = 0.5; // units between tick and text
  const tickWidth = 0.02;
  const tickHeight = 0.14;

  items.forEach((item, idx) => {
    // Tick before text (except first)
    if (idx > 0) {
      const tick = createTick();
      tick.position.set(cursorX - gap - tickWidth / 2, 0, 0.02);
      stripGroup.add(tick);
      cursorX -= gap;
    }

    // Text
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 0.06 * 13,
    });
    txt.position.set(cursorX, 0, 0.02);
    stripGroup.add(txt);
    // Approximate width: assume 0.6 per character (scene units) – simple heuristic
    const approxCharWidth = 0.6;
    const txtWidth = item.text.length * approxCharWidth;
    cursorX += txtWidth;

    // Tick after text
    const tick = createTick();
    tick.position.set(cursorX + gap + tickWidth / 2, 0, 0.02);
    stripGroup.add(tick);
    cursorX += gap;
  });

  // Duplicate strip for seamless looping
  const stripLength = cursorX;
  const stripCopy = stripGroup.clone(true);
  stripCopy.position.x = stripLength;
  root.add(stripGroup);
  root.add(stripCopy);

  // ---------- CINEMATIC PRIMITIVE ----------
  const fly = ctx.primitives['fly-through'](root, {
    depthUnits: 0,
    speed: 0.4,
  });

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // Dispose geometries and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    stripGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry.dispose();
        obj.material.dispose();
      }
    });
    stripCopy.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry.dispose();
        obj.material.dispose();
      }
    });
    // Cleanup primitive
    if (fly && typeof fly.cleanup === 'function') {
      fly.cleanup();
    }
  };

  return root;
}
